import { useState, useEffect } from 'react';
import { useWebSocket } from './hooks/useWebSocket';
import {
  startBackend,
  stopBackend,
  getBackendStatus,
  healthCheck,
  getBackendInfo,
  pingBackend,
  type BackendStatus,
  type BackendInfo
} from './services/backend';

function App() {
  const [backendStatus, setBackendStatus] = useState<BackendStatus | null>(null);
  const [backendInfo, setBackendInfo] = useState<BackendInfo | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pingResult, setPingResult] = useState<string | null>(null);

  const { isConnected, lastMessage, sendMessage, connect, disconnect } = useWebSocket();

  // Check backend status on mount
  useEffect(() => {
    const checkStatus = async () => {
      try {
        const status = await getBackendStatus();
        setBackendStatus(status);
      } catch (err) {
        console.error('Failed to get backend status:', err);
      }
    };
    checkStatus();
  }, []);

  const handleStartBackend = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const status = await startBackend();
      setBackendStatus(status);

      // Wait a bit then get backend info
      await new Promise(resolve => setTimeout(resolve, 1000));
      try {
        const info = await getBackendInfo();
        setBackendInfo(info);
      } catch {
        console.log('Backend info not available yet');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to start backend');
    } finally {
      setIsLoading(false);
    }
  };

  const handleStopBackend = async () => {
    setIsLoading(true);
    setError(null);
    try {
      await stopBackend();
      setBackendStatus({ running: false, port: null });
      setBackendInfo(null);
      disconnect();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to stop backend');
    } finally {
      setIsLoading(false);
    }
  };

  const handleHealthCheck = async () => {
    try {
      const result = await healthCheck();
      setError(null);
      setPingResult(`Health: ${result.status} at ${result.timestamp}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Health check failed');
    }
  };

  const handlePing = async () => {
    try {
      const result = await pingBackend();
      setError(null);
      setPingResult(`API Ping: ${result.message} at ${result.timestamp}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Ping failed');
    }
  };

  const handleWebSocketPing = () => {
    sendMessage({ type: 'ping' });
  };

  const handleWebSocketEcho = () => {
    sendMessage({ type: 'echo', data: 'Hello from React!' });
  };

  return (
    <div className="min-h-screen bg-surface-900 text-white p-8">
      <div className="max-w-4xl mx-auto">
        <header className="mb-8">
          <h1 className="text-4xl font-bold text-primary-400 mb-2">ScreenToGif</h1>
          <p className="text-surface-400">React + Tauri + C# Backend</p>
        </header>

        {error && (
          <div className="bg-red-900/50 border border-red-500 text-red-200 px-4 py-3 rounded-lg mb-6">
            {error}
          </div>
        )}

        {/* Backend Status Card */}
        <div className="bg-surface-800 rounded-xl p-6 mb-6 border border-surface-700">
          <h2 className="text-xl font-semibold mb-4 text-primary-300">Backend Status</h2>

          <div className="flex items-center gap-4 mb-4">
            <div className={`w-3 h-3 rounded-full ${backendStatus?.running ? 'bg-green-500' : 'bg-red-500'}`} />
            <span className="text-surface-300">
              {backendStatus?.running ? `Running on port ${backendStatus.port}` : 'Not running'}
            </span>
          </div>

          {backendInfo && (
            <div className="bg-surface-900 rounded-lg p-4 mb-4 font-mono text-sm">
              <p><span className="text-surface-500">Name:</span> {backendInfo.name}</p>
              <p><span className="text-surface-500">Version:</span> {backendInfo.version}</p>
              <p><span className="text-surface-500">Platform:</span> {backendInfo.platform}</p>
              <p><span className="text-surface-500">Runtime:</span> {backendInfo.runtime}</p>
            </div>
          )}

          <div className="flex gap-3">
            <button
              onClick={handleStartBackend}
              disabled={isLoading || backendStatus?.running}
              className="px-4 py-2 bg-primary-600 hover:bg-primary-500 disabled:bg-surface-600 disabled:cursor-not-allowed rounded-lg transition-colors"
            >
              {isLoading ? 'Starting...' : 'Start Backend'}
            </button>
            <button
              onClick={handleStopBackend}
              disabled={isLoading || !backendStatus?.running}
              className="px-4 py-2 bg-red-600 hover:bg-red-500 disabled:bg-surface-600 disabled:cursor-not-allowed rounded-lg transition-colors"
            >
              Stop Backend
            </button>
          </div>
        </div>

        {/* API Testing Card */}
        <div className="bg-surface-800 rounded-xl p-6 mb-6 border border-surface-700">
          <h2 className="text-xl font-semibold mb-4 text-primary-300">API Testing</h2>

          {pingResult && (
            <div className="bg-surface-900 rounded-lg p-3 mb-4 font-mono text-sm text-green-400">
              {pingResult}
            </div>
          )}

          <div className="flex gap-3">
            <button
              onClick={handleHealthCheck}
              disabled={!backendStatus?.running}
              className="px-4 py-2 bg-surface-600 hover:bg-surface-500 disabled:bg-surface-700 disabled:cursor-not-allowed rounded-lg transition-colors"
            >
              Health Check
            </button>
            <button
              onClick={handlePing}
              disabled={!backendStatus?.running}
              className="px-4 py-2 bg-surface-600 hover:bg-surface-500 disabled:bg-surface-700 disabled:cursor-not-allowed rounded-lg transition-colors"
            >
              Ping API
            </button>
          </div>
        </div>

        {/* WebSocket Card */}
        <div className="bg-surface-800 rounded-xl p-6 border border-surface-700">
          <h2 className="text-xl font-semibold mb-4 text-primary-300">WebSocket Connection</h2>

          <div className="flex items-center gap-4 mb-4">
            <div className={`w-3 h-3 rounded-full ${isConnected ? 'bg-green-500' : 'bg-yellow-500'}`} />
            <span className="text-surface-300">
              {isConnected ? 'Connected' : 'Disconnected'}
            </span>
          </div>

          {lastMessage && (
            <div className="bg-surface-900 rounded-lg p-4 mb-4 font-mono text-sm">
              <p className="text-surface-500 mb-1">Last Message:</p>
              <pre className="text-green-400 whitespace-pre-wrap">
                {JSON.stringify(lastMessage, null, 2)}
              </pre>
            </div>
          )}

          <div className="flex gap-3 flex-wrap">
            <button
              onClick={connect}
              disabled={isConnected || !backendStatus?.running}
              className="px-4 py-2 bg-primary-600 hover:bg-primary-500 disabled:bg-surface-600 disabled:cursor-not-allowed rounded-lg transition-colors"
            >
              Connect
            </button>
            <button
              onClick={disconnect}
              disabled={!isConnected}
              className="px-4 py-2 bg-red-600 hover:bg-red-500 disabled:bg-surface-600 disabled:cursor-not-allowed rounded-lg transition-colors"
            >
              Disconnect
            </button>
            <button
              onClick={handleWebSocketPing}
              disabled={!isConnected}
              className="px-4 py-2 bg-surface-600 hover:bg-surface-500 disabled:bg-surface-700 disabled:cursor-not-allowed rounded-lg transition-colors"
            >
              WS Ping
            </button>
            <button
              onClick={handleWebSocketEcho}
              disabled={!isConnected}
              className="px-4 py-2 bg-surface-600 hover:bg-surface-500 disabled:bg-surface-700 disabled:cursor-not-allowed rounded-lg transition-colors"
            >
              WS Echo
            </button>
          </div>
        </div>

        <footer className="mt-8 text-center text-surface-500 text-sm">
          Built with Tauri 2.0 + React + TypeScript + TailwindCSS + C# Backend
        </footer>
      </div>
    </div>
  );
}

export default App;

/**
 * Stores Index
 * Re-exports all Zustand stores for convenient imports
 */

// Recorder Store
export { useRecorderStore, selectCaptureState, selectIsRecording, selectCaptureOptions } from './recorderStore';

// Editor Store
export {
  useEditorStore,
  selectIsPlaying,
  selectSelectedFrameCount,
  selectHasSelection,
} from './editorStore';
export type { PlaybackState, SelectionMode, EditorTool, ZoomPreset } from './editorStore';

// Project Store
export {
  useProjectStore,
  selectHasProject,
  selectIsDirty,
  selectFrameCount,
  selectProjectTitle,
} from './projectStore';

// Export Store
export {
  useExportStore,
  selectIsEncoding,
  selectEncodingProgress,
  selectAllPresets,
} from './exportStore';

// Settings Store
export {
  useSettingsStore,
  selectTheme,
  selectLocale,
  selectHotkeys,
} from './settingsStore';
export type { AppTheme, AppLocale, StartupMode, ThumbnailQuality, HotkeyBinding } from './settingsStore';

// UI Store
export {
  useUIStore,
  selectCurrentView,
  selectIsLoading,
  selectToasts,
  selectIsBackendConnected,
} from './uiStore';
export type { Toast, ToastType, ModalType, AppView, PanelId } from './uiStore';

/**
 * Export Store
 * Manages export configuration, presets, encoding progress, and upload state
 */

import { create } from 'zustand';
import { subscribeWithSelector, persist } from 'zustand/middleware';
import type {
  EncodingOptions,
  EncodingProgress,
  ExportPreset,
  PresetCategory,
  OutputFormat,
  UploadConfig,
  UploadProgress,
  UploadResult,
  RecentExport,
  ExportQueueItem,
} from '../api/types';

interface ExportState {
  // Current export configuration
  currentOptions: EncodingOptions | null;
  selectedPresetId: string | null;
  outputPath: string;
  outputFileName: string;

  // Presets
  builtInPresets: ExportPreset[];
  customPresets: ExportPreset[];
  defaultPresetId: string | null;

  // Encoding state
  isEncoding: boolean;
  currentJobId: string | null;
  encodingProgress: EncodingProgress | null;

  // Export queue
  queue: ExportQueueItem[];
  isQueueProcessing: boolean;
  maxConcurrentJobs: number;

  // Upload state
  isUploading: boolean;
  uploadProgress: UploadProgress | null;
  lastUploadResult: UploadResult | null;
  uploadConfig: UploadConfig | null;

  // Recent exports
  recentExports: RecentExport[];
  maxRecentExports: number;

  // UI state
  showAdvancedOptions: boolean;
  selectedFormatTab: OutputFormat;

  // Error state
  error: string | null;
}

interface ExportActions {
  // Configuration
  setCurrentOptions: (options: EncodingOptions) => void;
  updateCurrentOptions: (updates: Partial<EncodingOptions>) => void;
  setSelectedPresetId: (presetId: string | null) => void;
  setOutputPath: (path: string) => void;
  setOutputFileName: (fileName: string) => void;
  applyPreset: (preset: ExportPreset) => void;

  // Presets
  setBuiltInPresets: (presets: ExportPreset[]) => void;
  addCustomPreset: (preset: ExportPreset) => void;
  updateCustomPreset: (presetId: string, updates: Partial<ExportPreset>) => void;
  removeCustomPreset: (presetId: string) => void;
  setDefaultPresetId: (presetId: string | null) => void;
  getPresetById: (presetId: string) => ExportPreset | undefined;
  getPresetsByCategory: (category: PresetCategory) => ExportPreset[];

  // Encoding
  startEncoding: (jobId: string) => void;
  updateEncodingProgress: (progress: EncodingProgress) => void;
  completeEncoding: (success: boolean, error?: string) => void;
  cancelEncoding: () => void;

  // Queue
  addToQueue: (item: Omit<ExportQueueItem, 'id' | 'status' | 'progress' | 'addedAt'>) => void;
  removeFromQueue: (itemId: string) => void;
  clearQueue: () => void;
  updateQueueItem: (itemId: string, updates: Partial<ExportQueueItem>) => void;
  startQueueProcessing: () => void;
  stopQueueProcessing: () => void;

  // Upload
  startUpload: (config: UploadConfig) => void;
  updateUploadProgress: (progress: UploadProgress) => void;
  completeUpload: (result: UploadResult) => void;
  cancelUpload: () => void;
  setUploadConfig: (config: UploadConfig | null) => void;

  // Recent exports
  addRecentExport: (exportInfo: RecentExport) => void;
  removeRecentExport: (exportId: string) => void;
  clearRecentExports: () => void;

  // UI
  setShowAdvancedOptions: (show: boolean) => void;
  toggleAdvancedOptions: () => void;
  setSelectedFormatTab: (format: OutputFormat) => void;

  // Error handling
  setError: (error: string | null) => void;
  clearError: () => void;

  // Reset
  reset: () => void;
  resetProgress: () => void;
}

// Default GIF encoding options
const defaultGifOptions: EncodingOptions = {
  format: 'gif',
  outputPath: '',
  gif: {
    encoder: 'screentogif',
    colorCount: 256,
    quantization: 'medianCut',
    dithering: 'floydSteinberg',
    quality: 80,
    loopCount: 0,
    enableTransparency: false,
    detectUnchangedPixels: true,
    paintTransparent: false,
  },
};

// Built-in presets
const defaultBuiltInPresets: ExportPreset[] = [
  {
    id: 'gif-standard',
    name: 'Standard GIF',
    description: 'Balanced quality and file size',
    category: 'gif',
    isBuiltIn: true,
    isDefault: true,
    options: { ...defaultGifOptions },
  },
  {
    id: 'gif-high-quality',
    name: 'High Quality GIF',
    description: 'Maximum quality, larger file size',
    category: 'gif',
    isBuiltIn: true,
    options: {
      ...defaultGifOptions,
      gif: { ...defaultGifOptions.gif!, colorCount: 256, quality: 100, dithering: 'floydSteinberg' },
    },
  },
  {
    id: 'gif-small-file',
    name: 'Small File GIF',
    description: 'Optimized for smallest file size',
    category: 'gif',
    isBuiltIn: true,
    options: {
