     1→import { useState, useEffect, useRef, useCallback } from 'react';
     2→
     3→/**
     4→ * Hook that debounces a value
     5→ */
     6→export function useDebounce<T>(value: T, delay: number): T {
     7→  const [debouncedValue, setDebouncedValue] = useState<T>(value);
     8→
     9→  useEffect(() => {
    10→    const timer = setTimeout(() => {
    11→      setDebouncedValue(value);
    12→    }, delay);
    13→
    14→    return () => {
    15→      clearTimeout(timer);
    16→    };
    17→  }, [value, delay]);
    18→
    19→  return debouncedValue;
    20→}
    21→
    22→/**
    23→ * Hook that returns a debounced callback function
    24→ */
    25→export function useDebouncedCallback<T extends (...args: Parameters<T>) => ReturnType<T>>(
    26→  callback: T,
    27→  delay: number,
    28→  deps: React.DependencyList = []
    29→): (...args: Parameters<T>) => void {
    30→  const timeoutRef = useRef<number | undefined>(undefined);
    31→  const callbackRef = useRef(callback);
    32→
    33→  // Update callback ref when callback changes
    34→  useEffect(() => {
    35→    callbackRef.current = callback;
    36→  }, [callback]);
    37→
    38→  // Cleanup on unmount
    39→  useEffect(() => {
    40→    return () => {
    41→      if (timeoutRef.current) {
    42→        clearTimeout(timeoutRef.current);
    43→      }
    44→    };
    45→  }, []);
    46→
    47→  return useCallback(
    48→    (...args: Parameters<T>) => {
    49→      if (timeoutRef.current) {
    50→        clearTimeout(timeoutRef.current);
    51→      }
    52→
    53→      timeoutRef.current = window.setTimeout(() => {
    54→        callbackRef.current(...args);
    55→      }, delay);
    56→    },
    57→    [delay, ...deps]
    58→  );
    59→}
    60→
    61→/**
    62→ * Hook that returns a debounced callback with immediate option
    63→ */
    64→export function useDebouncedCallbackImmediate<T extends (...args: Parameters<T>) => ReturnType<T>>(
    65→  callback: T,
    66→  delay: number,
    67→  immediate: boolean = false
    68→): [(...args: Parameters<T>) => void, () => void, boolean] {
